mapper.select:
SELECT a.menu_id
FROM t_sys_user_home_quick_launch a
WHERE a.user_id = #{userId}
  AND a.scope_type = #{scope}

    AND a.app_id = #{appId}
    AND a.app_id IS NULL

ORDER BY a.seq, a.id

mapper.delete:
DELETE FROM t_sys_user_home_quick_launch a
WHERE a.user_id = #{userId}
  AND a.scope_type = #{scope}

    AND a.app_id = #{appId}
    AND a.app_id IS NULL
